#!/usr/bin/env python3
"""Assemble the approved compositions and immutable sources into a local companion.

The same scene adapter is used for live playback and deterministic export seeks.
This builder never touches the original banner, runtime, profile, CI or locks.
"""
from pathlib import Path
import base64,hashlib,json,re
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'showcase/capri/source-match';SOURCE=BASE/'source';OUT=BASE/'companion'
def fragment(name):
 text=(SOURCE/'design/approved'/name).read_text()
 text=re.sub(r'<script\b[^>]*>.*?</script>','',text,flags=re.S)
 return re.sub(r"@import\s+url\([^)]*\);",'',text)
def uri(path,mime):
 return 'data:'+mime+';base64,'+base64.b64encode(path.read_bytes()).decode()
def main():
 OUT.mkdir(exist_ok=True)
 for name,seed in [('ocean-source.js',41729),('horizon-source.js',19381)]:
  original=(SOURCE/'native'/name).read_text();first=original.index('{')+1
  rng=f'\n let seed={seed}; function seededRandom(){{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;}}\n'
  adapted=(original[:first]+rng+original[first:]).replace('Math.random()','seededRandom()')
  (OUT/name).write_text('/* Adapted from immutable source/native/'+name+'; deterministic per-instance seed only. */\n'+adapted)
 parts=[fragment('handoff-comic-full-sprites.fragment.html'),fragment('capri-source-scenes.fragment.html'),fragment('capri-reference-composites.fragment.html')]
 # Current role names supplement the approved teaching labels without new banners.
 parts[0]=parts[0].replace('Scope, sources and acceptance checks.','Thinker: scope, sources and acceptance checks.').replace('The latest correction travels with the task.','Doer: the correction travels with the task.').replace('Request, patch and evidence together.','Reviewer: request, patch and evidence together.')
 source_fragment=(SOURCE/'design/approved/capri-source-scenes.fragment.html').read_text()
 match=re.search(r'<script[^>]*id="capri-source-data"[^>]*>(.*?)</script>',source_fragment,re.S)
 poster=json.loads(match.group(1))['horizonPoster']
 data={'horizonPoster':poster,'rig':json.loads((BASE/'actor/RIG.json').read_text()),'catEyes':json.loads((BASE/'plates/CAT_EYES.json').read_text()),'budget':json.loads((SOURCE/'assets/data/context-budget.json').read_text())}
 for pose in data['rig']['poses'].values():
  for part in pose['parts']:part['src']=uri(BASE/'actor'/Path(part['src']).name,'image/png')
 data['plates']={record['name']:{'src':uri(BASE/'plates'/record['file'],'video/mp4'),'duration':record['duration']} for record in json.loads((BASE/'plates/PLATES.json').read_text())}
 style='''.export{scrollbar-width:none}.export::-webkit-scrollbar{display:none}[hidden]{display:none!important}@font-face{font-family:Manrope;src:url('../source/assets/fonts/Manrope/Manrope-Variable.ttf')}@font-face{font-family:Inter;src:url('../source/assets/fonts/Inter/Inter-Variable.ttf')}@font-face{font-family:'Martian Mono';src:url('../source/assets/fonts/MartianMono/MartianMono-Variable.ttf')}*{box-sizing:border-box}body{margin:0;background:#f4f1ee;color:#100a19;font:16px/1.5 Inter,Arial,sans-serif}main{max-width:1240px;margin:auto;padding:24px}nav{display:flex;flex-wrap:wrap;gap:16px;margin-bottom:24px}a{color:inherit;text-underline-offset:4px}button,input{font:inherit}button{border:1px solid #bcb7c6;border-radius:3px;padding:9px 14px;background:#f4f1ee;color:#100a19;cursor:pointer}:focus-visible{outline:3px solid #ff1265;outline-offset:4px}h1,h2,h3{font-family:Manrope,sans-serif;font-weight:500;font-style:normal}h1{font-size:32px}h2{font-size:28px}p{max-width:76ch}.viz-controls{display:flex;flex-wrap:wrap;align-items:center;gap:12px;padding:16px 0}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.cp-media{display:none}.native-text{padding:24px 0}.native-text table{border-collapse:collapse;display:block;max-width:100%;overflow-x:auto}.native-text td,.native-text th{padding:10px 16px;border-bottom:1px solid #bcb7c6;text-align:left}.scene-tools{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:14px 0;color:#100a19}.scene-tools input{min-width:100px;max-width:100%;flex:1}.scene-status{font-size:14px;min-height:1.5em}.cp-grid,.cs-grid{margin:24px 0}.cp-panel,.cs-panel{scroll-margin-top:24px}.cp-copy p,.cs-caption p{font-size:16px!important}.cp-card-copy{font-size:clamp(10px,1.5vw,17px)!important}.export body{background:#100a19}.export main{max-width:none;margin:0;padding:0}.export nav,.export .native-text,.export .viz-controls,.export .scene-tools,.export .scene-status,.export .cs-caption details,.export .hcf-card details{display:none!important}.export .cp-grid,.export .cs-grid{display:block!important;margin:0!important}.export .cp-panel,.export .cs-panel{margin:0}.export .cp-copy,.export .cs-caption{padding:24px 32px 30px}.export .cp-copy h3,.export .cs-caption h3{font-size:32px!important}.export .cp-copy p,.export .cs-caption p{font-size:23px!important}.export .hcf-comic{padding:28px!important}.export .hcf-intro h2{font-size:38px!important}.export .hcf-intro p,.export .hcf-copy{font-size:20px!important}.export .hcf-end{font-size:18px!important}.export.portrait .hcf-grid{grid-template-columns:1fr!important;gap:32px!important}.export.portrait .hcf-card{max-width:none!important;margin:0!important;padding-top:0!important}.export.portrait .hcf-model{max-width:440px!important;max-height:360px!important;margin:0 auto 20px!important}.export.portrait .hcf-intro h2{font-size:42px!important}.export.portrait .hcf-copy,.export.portrait .hcf-intro p{font-size:28px!important}.export.portrait .hcf-card h3{font-size:38px!important}.export.portrait .hcf-end{font-size:25px!important}.export.portrait .cp-copy p,.export.portrait .cs-caption p{font-size:28px!important}.export.portrait .cp-copy h3,.export.portrait .cs-caption h3{font-size:36px!important}.export.portrait .cs-brief h3{font-size:30px!important}.export.portrait .cs-paper{font-size:21px!important}.export .hcf-packet{font-size:18px!important}.export .cp-brief summary{list-style:none;cursor:default}.export .cp-brief summary::-webkit-details-marker{display:none}.export .cp-card-copy{font-size:18px!important}.export.portrait .cp-card-copy{font-size:23px!important}.scene-tools button{min-height:44px}@media(prefers-color-scheme:dark){body{background:#0d1117;color:#f4f1ee}.scene-tools{color:#f4f1ee}}@media(max-width:650px){main{padding:16px}#capri-source-scenes .cs-grid,#capri-reference-composites .cp-grid{grid-template-columns:1fr}.cp-copy,.cs-caption{padding:18px!important}.cp-card-copy{font-size:11px!important}}'''
 intro='''<nav><a href="../../../../README.md">Repository README</a><a href="../../../../docs/README_STATIC.md">Complete static edition</a><a href="#handoff-comic-full-sprites">The comic</a><a href="#capri-source-scenes">Sharks and horizon</a><a href="#capri-reference-composites">Source composites</a></nav>'''
 mechanism='''<section class="native-text"><h2>Supply the next decision.</h2><p>A handoff carries the original request, latest correction, relevant source, scope and acceptance checks. Originals stay retrievable. Ordered stages have one write owner; uncertain effects hold. The human decides what ships.</p><p><b>Authored fixture example:</b> change <code>label.py</code> only. Trim outer whitespace; preserve case and internal spaces. Blank input becomes <code>Untitled</code>; non-strings raise <code>TypeError</code>. This illustration is not a completed native run.</p><p><a href="../../../../evaluation/fixtures/A/INITIAL.md">Original request</a> · <a href="../../../../evaluation/fixtures/A/CORRECTION.md">Latest correction</a></p></section>'''
 numbers='''<section class="native-text" id="worked-example"><h2>Worked example: assumed input tokens.</h2><p><b>Not a measured CAPRI run.</b> Six assumed requests total 180,000 for growing history, 90,000 for a curated single session and 60,000 for scoped roles. Scoped input is 66.7%/33.3% lower under these assumptions; sufficient information and equal quality have not been established.</p><table><tr><th>Request</th><th>Growing</th><th>Curated</th><th>Scoped</th></tr>'''+''.join(f'<tr><td>{i+1}</td><td>{a:,}</td><td>{b:,}</td><td>{c:,}</td></tr>' for i,(a,b,c) in enumerate(zip(*[series['values'] for series in data['budget']['series']])))+'''</table><p>A long stable cached prefix can cost less than several shorter uncached requests. At a hypothetical cached relative rate of 0.05, 50k uncached + 130k cached inputs cost 56.5k weighted units, below 60k uncached scoped units. These are normalized assumptions, not prices. Output, coordination, retries and compaction also matter. Prefix caching does not delete instructions or free context-window capacity.</p><p><a href="../../../../docs/BENCHMARK_PROTOCOL.md">Current benchmark protocol</a> · <a href="../../../../docs/STATUS.md">Native qualification remains experimental/BLOCKED</a></p></section>'''
 rig=data.pop('rig')
 (OUT/'actor-data.js').write_text('window.CAPRI_RIG='+json.dumps(rig,separators=(',',':'))+';\n')
 page=f'<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAPRI · source-match companion</title><style>{style}</style><main>{intro}{parts[0]}{mechanism}{parts[1]}{numbers}{parts[2]}<p class="native-text">Private source-reference composites and reconstructed character acting; not a controller recording. <a href="../../../../docs/SOURCE_MATCH.md">Sources, rights and build record</a>.</p></main><script src="actor-data.js"></script><script type="application/json" id="scene-data">{json.dumps(data,separators=(",",":"))}</script><script src="actor.js"></script><script src="ocean-source.js"></script><script src="horizon-source.js"></script><script src="scenes.js"></script></html>'
 for family in ['Manrope','Inter','MartianMono']:
  font=SOURCE/'assets/fonts'/family/(family+'-Variable.ttf')
  page=page.replace('../source/assets/fonts/'+family+'/'+font.name,uri(font,'font/ttf'))
 for script in ['actor.js','ocean-source.js','horizon-source.js','scenes.js']:
  page=page.replace('<script src="'+script+'"></script>','<script>'+(OUT/script).read_text()+'</script>')
 (OUT/'index.html').write_text(page)
 proof="""<!doctype html><html lang="en"><meta charset="utf-8"><title>Capri alpha and joint proof</title><style>body{margin:0;background:#100a19}canvas{width:100%;height:auto}</style><canvas width="1200" height="1200"></canvas><script src="actor.js"></script><script>const actor=new CapriActor(__RIG__);actor.ready.then(()=>{const c=document.querySelector('canvas').getContext('2d');for(let row=0;row<4;row++)for(const [col,name] of ['plan','build','review'].entries()){c.save();c.translate(col*400,row*300);c.fillStyle=row===1?'#f4f1ee':'#100a19';c.fillRect(0,0,400,300);if(row===2)for(let y=0;y<300;y+=20)for(let x=0;x<400;x+=20){c.fillStyle=(x/20+y/20)%2?'#bcb7c6':'#f4f1ee';c.fillRect(x,y,20,20);}const t=[0,800,1400,1800][row];actor.draw(c,name,t,200,80,.20);c.fillStyle=row===1||row===2?'#100a19':'#f4f1ee';c.font='16px sans-serif';c.fillText(name+' · '+t+' ms',16,280);c.restore();}document.body.dataset.ready='true';});</script></html>"""
 (OUT/'rig-proof.html').write_text(proof.replace('__RIG__',json.dumps(rig,separators=(',',':'))).replace('<script src="actor.js"></script>','<script>'+(OUT/'actor.js').read_text()+'</script>'))
 print('Companion assembled; immutable source preserved',flush=True)
if __name__=='__main__':main()
